import{_ as r,C as s,o as n,c as i,aj as e,G as a}from"./chunks/framework.BwH0p-pt.js";const b=JSON.parse('{"title":"AI Agent Chat","description":"","frontmatter":{},"headers":[],"relativePath":"2.1/ai-agent/ai-agent-chat.md","filePath":"2.1/ai-agent/ai-agent-chat.md","lastUpdated":1788942616000}'),d={name:"2.1/ai-agent/ai-agent-chat.md"};function l(c,t,h,u,g,p){const o=s("ImagePopup");return n(),i("div",null,[t[0]||(t[0]=e('<h1 id="ai-agent-chat" tabindex="-1">AI Agent Chat <a class="header-anchor" href="#ai-agent-chat" aria-label="Permalink to &quot;AI Agent Chat&quot;">​</a></h1><p>The <strong>AI Agent Chat</strong> is the conversational UI for Agentic PIM. From one chat window you can manage products, categories, attributes, data quality, and bulk operations — just by describing what you need.</p><h2 id="what-does-the-ai-agent-chat-do" tabindex="-1">What does the AI Agent Chat do? <a class="header-anchor" href="#what-does-the-ai-agent-chat-do" aria-label="Permalink to &quot;What does the AI Agent Chat do?&quot;">​</a></h2><p>The chat panel is a single entry point for <strong>30+ PIM tools</strong>. When you type a message, the agent:</p><ul><li>Interprets your intent.</li><li>Picks one or more tools to call (create product, search, bulk-edit, generate content, manage associations, etc.).</li><li>Runs the tools against real UnoPim data, inside your ACL permissions.</li><li>Streams the results back into the chat in real time.</li></ul><p>Anything you can do from the admin UI, you can do by asking for it in the chat — and the agent can chain several steps into one request, so tasks that would take many clicks collapse into a single instruction.</p><h2 id="how-does-it-work" tabindex="-1">How does it work? <a class="header-anchor" href="#how-does-it-work" aria-label="Permalink to &quot;How does it work?&quot;">​</a></h2>',7)),a(o,{src:"/assets/2.1/images/ai-agent/agentic-pim-pipeline.png",alt:"Agentic PIM Pipeline — 5-Step Workflow"}),t[1]||(t[1]=e('<p>The Platform and Model used for this reasoning loop are configured under <strong>Magic AI → Settings → Agentic PIM</strong>. The personality (tone, temperature, max tokens) comes from the active <strong>System Prompt</strong>.</p><h2 id="opening-the-ai-agent-chat" tabindex="-1">Opening the AI Agent Chat <a class="header-anchor" href="#opening-the-ai-agent-chat" aria-label="Permalink to &quot;Opening the AI Agent Chat&quot;">​</a></h2><p>Click the floating <strong>star icon</strong> at the bottom-right of any admin page. The chat panel slides in from the right edge with the header <strong>&quot;Agenting PIM — AI-powered operations&quot;</strong>.</p>',3)),a(o,{src:"/assets/2.1/images/ai-agent/ai-agent-chat.png",alt:"AI Agent Chat"}),t[2]||(t[2]=e("<p>A settings gear ⚙ in the panel header jumps to <code>/admin/ai-agent/settings</code> (which resolves to <strong>Magic AI → Settings</strong>), where you can configure platforms, models, and budgets.</p><p>The panel has three tabs:</p><ul><li><strong>Capabilities</strong> — Browse the 30+ tools the agent can call.</li><li><strong>Chat</strong> — Conversational interface. When empty, it shows <em>&quot;How can I help with your catalog?&quot;</em> under a star icon and the header <strong>General Chat</strong>.</li><li><strong>Sessions</strong> — Your past conversations. A numeric badge on the tab shows how many sessions are unread.</li></ul>",3)),a(o,{src:"/assets/2.1/images/ai-agent/ai-agent-chat-tab.png",alt:"AI Agent Chat Tab"}),t[3]||(t[3]=e('<p>Once opened, the chat panel slides in from the right side of the screen. You can start typing your request immediately.</p><h2 id="capabilities-tab" tabindex="-1">Capabilities Tab <a class="header-anchor" href="#capabilities-tab" aria-label="Permalink to &quot;Capabilities Tab&quot;">​</a></h2><p>The Capabilities tab lists every tool the agent can invoke. Each tool represents a specific PIM operation that you can trigger through natural language — you don&#39;t call tools by name, you describe what you want and the agent picks the right one.</p><table tabindex="0"><thead><tr><th>#</th><th>Tool</th><th>What it does</th></tr></thead><tbody><tr><td>1</td><td><strong>Create from Image</strong></td><td>Upload photos to auto-create products</td></tr><tr><td>2</td><td><strong>Update Products</strong></td><td>Update attributes/status by SKU</td></tr><tr><td>3</td><td><strong>Search Products</strong></td><td>Find products by SKU, name, or status</td></tr><tr><td>4</td><td><strong>Find Similar</strong></td><td>Find similar products using AI</td></tr><tr><td>5</td><td><strong>Generate Content</strong></td><td>AI-generated name, description &amp; SEO</td></tr><tr><td>6</td><td><strong>Generate Image</strong></td><td>Create product images from text</td></tr><tr><td>7</td><td><strong>Edit Product Image</strong></td><td>Background removal, enhance &amp; retouch</td></tr><tr><td>8</td><td><strong>Assign Categories</strong></td><td>Assign category paths to products</td></tr><tr><td>9</td><td><strong>List Attributes</strong></td><td>View family attributes &amp; options</td></tr><tr><td>10</td><td><strong>Export Products</strong></td><td>Generate CSV/XLSX export</td></tr><tr><td>11</td><td><strong>Bulk Import CSV</strong></td><td>Upload CSV/XLSX to batch update — runs as a background queued job</td></tr><tr><td>12</td><td><strong>Delete Products</strong></td><td>Remove products by SKU list</td></tr><tr><td>13</td><td><strong>Create Category</strong></td><td>Add new categories to the catalog</td></tr><tr><td>14</td><td><strong>Category Tree</strong></td><td>View full category hierarchy</td></tr><tr><td>15</td><td><strong>Create Attribute</strong></td><td>Add new product attributes</td></tr><tr><td>16</td><td><strong>Manage Options</strong></td><td>Add or list attribute options</td></tr><tr><td>17</td><td><strong>Attribute Families</strong></td><td>List, create, or inspect families</td></tr><tr><td>18</td><td><strong>Bulk Edit</strong></td><td>Mass update products by rules</td></tr><tr><td>19</td><td><strong>Catalog Summary</strong></td><td>Stats, counts &amp; recent activity</td></tr><tr><td>20</td><td><strong>Channels</strong></td><td>View channels, locales &amp; currencies</td></tr><tr><td>21</td><td><strong>Users</strong></td><td>View admin users &amp; details</td></tr><tr><td>22</td><td><strong>Roles</strong></td><td>View roles &amp; permissions</td></tr><tr><td>23</td><td><strong>Ask Anything</strong></td><td>Free-form PIM assistant</td></tr><tr><td>24</td><td><strong>Manage Associations</strong></td><td>Add, remove, or list related/up-sell/cross-sell products via natural language</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Every tool respects your ACL permissions. If your admin role doesn&#39;t allow a particular operation, the corresponding tool silently does not execute — the agent can never bypass your role.</p></div><h2 id="bulk-import-csv-—-now-queued" tabindex="-1">Bulk Import CSV — now queued <a class="header-anchor" href="#bulk-import-csv-—-now-queued" aria-label="Permalink to &quot;Bulk Import CSV — now queued&quot;">​</a></h2><p>The <strong>Bulk Import CSV</strong> tool previously processed the entire file inline, inside the HTTP request. That worked for a few hundred rows, but timed out on larger uploads. In v2.1.0 the tool extracts the heavy lifting into a dedicated queued job — <strong><code>ImportProductsJob</code></strong> — so you can reliably push <strong>10,000+ products</strong> in a single AI Agent message.</p><h3 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h3><ol><li>You ask the agent something like <em>&quot;import these products&quot;</em> and attach a CSV/XLSX.</li><li>The agent validates the file, opens a <strong>Job Track</strong> record (visible from the <strong>Job Tracker</strong> page), and dispatches one <code>ImportProductsJob</code> to the queue.</li><li>The job processes every row, recording results in a <code>JobTrackBatch</code>. The original HTTP request returns immediately with a job ID — you can keep chatting while the import runs.</li><li>The agent reports progress in the chat as the job advances. When it finishes, you get a summary (<code>created</code>, <code>updated</code>, errors).</li></ol><h3 id="import-modes" tabindex="-1">Import modes <a class="header-anchor" href="#import-modes" aria-label="Permalink to &quot;Import modes&quot;">​</a></h3><p>The agent can run the import in one of three modes — it picks based on your wording, but you can be explicit:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Behaviour</th><th>When to use</th></tr></thead><tbody><tr><td><strong><code>create_or_update</code></strong> <em>(default)</em></td><td>Updates existing SKUs, creates new ones.</td><td>Mixed-batch imports.</td></tr><tr><td><strong><code>create_only</code></strong></td><td>Only creates new SKUs — existing rows are <strong>skipped</strong>.</td><td>First-time loads where you want to avoid touching existing data.</td></tr><tr><td><strong><code>update_only</code></strong></td><td>Only updates existing SKUs — new SKUs are <strong>skipped</strong>.</td><td>Bulk corrections on a known SKU set.</td></tr></tbody></table><h3 id="job-behaviour" tabindex="-1">Job behaviour <a class="header-anchor" href="#job-behaviour" aria-label="Permalink to &quot;Job behaviour&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Value</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Timeout</strong></td><td><code>3600</code> seconds (1 hour)</td><td>Generous ceiling for very large imports.</td></tr><tr><td><strong>Tries</strong></td><td><code>1</code></td><td>The job is <strong>not</strong> retried on failure — partial results are recorded and the job is marked <code>failed</code>. Re-run the import from the AI Agent after you&#39;ve fixed the source file.</td></tr><tr><td><strong>Queue</strong></td><td><code>default</code></td><td>Make sure your <code>queue:work --queue=</code> list includes <code>default</code> (it does in the documented <a href="./../configuration/webhooks.html#running-the-queue-worker">worker command</a>).</td></tr></tbody></table><h3 id="what-gets-recorded" tabindex="-1">What gets recorded <a class="header-anchor" href="#what-gets-recorded" aria-label="Permalink to &quot;What gets recorded&quot;">​</a></h3><p>Every import dispatches into the standard UnoPim <strong>Data Transfer pipeline</strong>, so you can monitor it the same way you monitor a normal CSV import:</p><ul><li><strong>Job Tracker</strong> → see this import in the list with state <code>processing</code> → <code>completed</code>.</li><li><strong>Per-batch summary</strong> → <code>processed_rows</code>, <code>created</code>, <code>updated</code>, errors.</li><li><strong>Errors</strong> → first 10 row-level errors are saved with the format <code>Row N (SKU: X): &lt;message&gt;</code> so you can fix the source file.</li></ul><div class="tip custom-block"><p class="custom-block-title">Why <code>$tries = 1</code>?</p><p>Bulk imports are not safely retryable from the start — re-running a half-finished import would re-process rows that already succeeded, plus double-process anything that failed mid-row. UnoPim deliberately bails after one attempt so you can decide how to recover. Use the error list in the Job Tracker to fix the source rows and re-import.</p></div><h2 id="chat-interface-layout" tabindex="-1">Chat Interface Layout <a class="header-anchor" href="#chat-interface-layout" aria-label="Permalink to &quot;Chat Interface Layout&quot;">​</a></h2><p>The chat interface consists of the following areas:</p><ul><li><strong>Message Area</strong> — Displays the conversation history between you and the AI Agent, including responses, tool outputs, and status updates.</li><li><strong>Input Field</strong> — A text input at the bottom where you type your commands or questions. Keyboard hint: <strong>Enter</strong> to send, <strong>Shift+Enter</strong> for a new line.</li><li><strong>Attachment (paperclip) icon</strong> — Attach a file (image, CSV) to the message.</li><li><strong>Platform dropdown</strong> — Pick which configured AI Platform handles this specific message (see below).</li><li><strong>Model dropdown</strong> — Pick which model on that platform handles this specific message.</li><li><strong>Send button</strong> — Submits your message to the AI Agent for processing.</li></ul><h3 id="choosing-a-platform-or-model-for-a-single-message" tabindex="-1">Choosing a Platform or Model for a single message <a class="header-anchor" href="#choosing-a-platform-or-model-for-a-single-message" aria-label="Permalink to &quot;Choosing a Platform or Model for a single message&quot;">​</a></h3><p>The chat input bar lets you override the default platform and model <strong>per message</strong>, without changing the global defaults under <strong>Magic AI → Settings</strong>.</p><table tabindex="0"><thead><tr><th>Dropdown</th><th>What it shows</th><th>Source</th></tr></thead><tbody><tr><td><strong>Platform</strong></td><td>Every enabled platform (e.g., <em>OpenAI (Openai)</em>).</td><td><strong>Magic AI → Platforms</strong></td></tr><tr><td><strong>Model</strong></td><td>Models enabled on the selected platform (e.g., <em>gpt-5.4</em>).</td><td>Models ticked on that platform</td></tr></tbody></table><p>The override lasts for one message; the next message reverts to whatever the dropdowns are currently showing.</p><p><strong>When this is useful:</strong></p><ul><li><strong>Cost control</strong> — route a simple lookup to a cheap, fast model while keeping a premium model for enrichment.</li><li><strong>Quality experiments</strong> — send the same prompt twice with different models and compare.</li><li><strong>Provider isolation</strong> — route sensitive prompts to a self-hosted Ollama platform without touching the global setting.</li></ul><p>If you want a change to stick for every user and every feature, edit <strong>Magic AI → Settings → Agentic PIM</strong> instead.</p><h2 id="types-of-commands" tabindex="-1">Types of Commands <a class="header-anchor" href="#types-of-commands" aria-label="Permalink to &quot;Types of Commands&quot;">​</a></h2><p>Below are the main categories of things you can ask the agent to do. Because the agent chooses tools from your intent, you don&#39;t need to remember tool names — just describe the outcome you want.</p><h3 id="product-operations" tabindex="-1">Product Operations <a class="header-anchor" href="#product-operations" aria-label="Permalink to &quot;Product Operations&quot;">​</a></h3><p>Create, update, search, and bulk-edit products.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;Create a simple product with SKU TSHIRT-001 and name Blue T-Shirt&quot;</li><li>&quot;Update the price of product SKU LAPTOP-PRO to 999.99&quot;</li><li>&quot;Search for all products in the Footwear category&quot;</li><li>&quot;Bulk update status to enabled for all products with SKU starting with SHOE&quot;</li></ul><h3 id="category-management" tabindex="-1">Category Management <a class="header-anchor" href="#category-management" aria-label="Permalink to &quot;Category Management&quot;">​</a></h3><p>Manage the category tree.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;Show me all root categories&quot;</li><li>&quot;List products assigned to the Electronics category&quot;</li></ul><h3 id="data-quality-reports" tabindex="-1">Data Quality Reports <a class="header-anchor" href="#data-quality-reports" aria-label="Permalink to &quot;Data Quality Reports&quot;">​</a></h3><p>Scan your catalog for missing or incomplete data and receive structured reports you can act on.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;Run a data quality scan on all products in the Clothing category&quot;</li><li>&quot;Which products are missing a description?&quot;</li><li>&quot;Show me products with completeness score below 50%&quot;</li></ul><h3 id="product-verification-quality-scoring" tabindex="-1">Product Verification &amp; Quality Scoring <a class="header-anchor" href="#product-verification-quality-scoring" aria-label="Permalink to &quot;Product Verification &amp; Quality Scoring&quot;">​</a></h3><p>Verify individual products against quality criteria.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;Check the completeness of product SKU JACKET-100&quot;</li><li>&quot;Verify data quality for all products in the Default family&quot;</li></ul><h3 id="auto-enrichment" tabindex="-1">Auto-Enrichment <a class="header-anchor" href="#auto-enrichment" aria-label="Permalink to &quot;Auto-Enrichment&quot;">​</a></h3><p>Have the agent fill in missing content — descriptions, SEO fields, etc. The agent uses whatever the product already has (name, category, attributes) to produce content that fits.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;Generate a short description for product SKU SNEAKER-200&quot;</li><li>&quot;Auto-fill missing meta descriptions for all products in the Accessories category&quot;</li><li>&quot;Enrich the SEO fields for product SKU WATCH-050&quot;</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Auto-enrichment works best when the product already has basic information like a name and category. The agent leans on that context to produce coherent, on-brand content.</p></div><h3 id="task-planning" tabindex="-1">Task Planning <a class="header-anchor" href="#task-planning" aria-label="Permalink to &quot;Task Planning&quot;">​</a></h3><p>For multi-step work, the agent builds a plan, shows it to you, and executes it step-by-step.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;Plan and execute: update all products in the Summer collection to have a 20% discount and a new promotional description&quot;</li><li>&quot;Create a task plan to review and enrich all products with missing images&quot;</li></ul><h3 id="bulk-transformations" tabindex="-1">Bulk Transformations <a class="header-anchor" href="#bulk-transformations" aria-label="Permalink to &quot;Bulk Transformations&quot;">​</a></h3><p>Apply transforms (append, prepend, replace) across many SKUs in one shot.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;Bulk update all products with status disabled to enabled&quot;</li><li>&quot;Change the category of all products with SKU prefix LEGACY to the Archive category&quot;</li></ul><h3 id="manage-associations" tabindex="-1">Manage Associations <a class="header-anchor" href="#manage-associations" aria-label="Permalink to &quot;Manage Associations&quot;">​</a></h3><p>Introduced in <strong>v2.0.x</strong>, the <strong>Manage Associations</strong> tool lets you add, remove, or list related products, up-sells, and cross-sells through conversation — no need to open each product individually.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;Add SKU BELT-100 as a cross-sell on SKU JEANS-200&quot;</li><li>&quot;Remove all up-sell products from SKU PHONE-CASE-BLACK&quot;</li><li>&quot;List cross-sell products linked to SKU LAPTOP-PRO&quot;</li><li>&quot;Mirror the related products of SKU SHIRT-001 onto SKU SHIRT-002&quot;</li></ul><h3 id="agent-memory-system" tabindex="-1">Agent Memory System <a class="header-anchor" href="#agent-memory-system" aria-label="Permalink to &quot;Agent Memory System&quot;">​</a></h3><p>The agent has a small long-term memory that persists across sessions. It uses two internal tools:</p><ul><li><strong>RememberFact</strong> — Stores a fact or preference you tell it to remember.</li><li><strong>RecallMemory</strong> — Retrieves remembered facts when they&#39;re relevant to the current request.</li></ul><p><strong>Example prompts:</strong></p><ul><li>&quot;Remember that our standard product description format starts with the brand name&quot;</li><li>&quot;Recall what I told you about our naming convention&quot;</li></ul><h3 id="content-feedback-loop" tabindex="-1">Content Feedback Loop <a class="header-anchor" href="#content-feedback-loop" aria-label="Permalink to &quot;Content Feedback Loop&quot;">​</a></h3><p>When the agent generates content, you can nudge it with feedback and it will adjust future outputs in the same session — and, if strong enough, remember the preference for next time.</p><p><strong>Example prompts:</strong></p><ul><li>&quot;That description is too long, make it shorter and more direct&quot;</li><li>&quot;I prefer a formal tone for product descriptions&quot;</li><li>&quot;Rewrite that but focus more on the material and durability&quot;</li></ul><h2 id="real-time-streaming-responses" tabindex="-1">Real-Time Streaming Responses <a class="header-anchor" href="#real-time-streaming-responses" aria-label="Permalink to &quot;Real-Time Streaming Responses&quot;">​</a></h2><p>Responses stream into the chat in real time using <strong>Server-Sent Events (SSE)</strong>. You see the agent&#39;s reasoning, tool calls, and results appear progressively instead of waiting for the whole response. For long operations (a 200-product bulk update, for instance) this lets you watch progress as it happens.</p><h2 id="sessions-tab" tabindex="-1">Sessions Tab <a class="header-anchor" href="#sessions-tab" aria-label="Permalink to &quot;Sessions Tab&quot;">​</a></h2><p>The Sessions tab lists every past chat. Each entry shows the session title, number of messages, and last-active date.</p>',76)),a(o,{src:"/assets/2.1/images/ai-agent/ai-agent-sessions.png",alt:"AI Agent Sessions"}),t[4]||(t[4]=e('<h3 id="managing-sessions" tabindex="-1">Managing Sessions <a class="header-anchor" href="#managing-sessions" aria-label="Permalink to &quot;Managing Sessions&quot;">​</a></h3><ul><li><strong>+ New Session</strong> — Start a clean conversation with no prior context. Useful when you switch to a different task.</li><li><strong>Delete session</strong> — Trash-icon button permanently removes a session. Irreversible.</li><li><strong>Resume a session</strong> — Click any entry to reopen it. Full history and context restore, so the agent picks up exactly where you left off.</li></ul><h3 id="session-persistence" tabindex="-1">Session Persistence <a class="header-anchor" href="#session-persistence" aria-label="Permalink to &quot;Session Persistence&quot;">​</a></h3><p>Sessions are database-backed, which means:</p><ul><li><strong>Page refreshes</strong> do not clear your conversation.</li><li><strong>Browser sessions</strong> are preserved — close the tab, come back later, resume.</li><li><strong>Context is preserved within a session</strong>, so the agent remembers what you discussed earlier in the same thread (&quot;apply the same change to SKU B&quot;).</li><li>Sessions persist <strong>across logins</strong>, so your history is always available when you sign back in.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Start a new session when switching to a different task. Focused sessions produce better tool choices because the agent isn&#39;t juggling unrelated context.</p></div>',6))])}const f=r(d,[["render",l]]);export{b as __pageData,f as default};
